/**
 * @distilled.cloud/scaleway — Scaleway API SDK for Effect.
 *
 * `./services` is generated by `scripts/generate.ts` from the Smithy models
 * in `.generated-specs` (written by `scripts/convert.ts` from the OpenAPI
 * documents mirrored at `specs/spec-mirror-scaleway/specs/`). Everything
 * else in this folder is hand-written.
 *
 * One module per Scaleway API service and version, named after it
 * (`instanceV1`, `k8sV1`, `lbZonedV1`, `accountProjectV3`, …). Auth is an
 * API secret key (`SCW_SECRET_KEY`) sent as `X-Auth-Token`; a call that
 * omits `region` / `zone` uses `SCW_DEFAULT_REGION` / `SCW_DEFAULT_ZONE`
 * (default `fr-par` / `fr-par-1`).
 *
 * @example
 * ```ts
 * import { Effect, Layer } from "effect";
 * import * as FetchHttpClient from "effect/http/FetchHttpClient";
 * import * as Scaleway from "@distilled.cloud/scaleway";
 *
 * const program = Effect.gen(function* () {
 *   const { servers } = yield* Scaleway.instanceV1.listServers({ zone: "fr-par-1" });
 *   return servers;
 * });
 *
 * program.pipe(
 *   Effect.provide(
 *     Layer.mergeAll(
 *       FetchHttpClient.layer,
 *       Scaleway.CredentialsFromEnv,
 *       Scaleway.ScalewayProtocol,
 *     ),
 *   ),
 *   Effect.runPromise,
 * );
 * ```
 */
export * from "./credentials.ts";
export * from "./errors.ts";
export * as T from "./traits.ts";
export {
  ScalewayProtocol,
  scalewayError,
  type ScalewayOpError,
  type ScalewayOpContext,
} from "./protocol.ts";
export { paginateByTotalCount, paginateToken } from "./pagination.ts";
export {
  streamChatCompletion,
  streamResponse,
  type ChatCompletionChunk,
  type ResponseStreamEvent,
} from "./streaming.ts";
export * as Retry from "./retry.ts";
export * from "./services/index.ts";
